diff --git a/src/http/auth-middleware.ts b/src/http/auth-middleware.ts
index bdb91e7..524d897 100644
--- a/src/http/auth-middleware.ts
+++ b/src/http/auth-middleware.ts
@@ -5,10 +5,11 @@ export function requireSession(sessions: SessionManager) {
     const id = req.cookies?.sid;
     const session = id ? await sessions.resolve(id) : undefined;
     if (!session) {
+      res.clearCookie("sid");
       res.status(401).end();
       return;
     }
-    req.session = session;
+    req.session = await sessions.touch(session);
     next();
   };
 }
diff --git a/src/http/login.ts b/src/http/login.ts
